// sass: CCTL
.version 9.4
.target sm_89
.address_size 64
.visible .entry cache_control(.param .u64 address, .param .u64 out) {
.reg .b32 %r<4>;
.reg .b64 %rd<4>;
ld.param.u64 %rd0, [address];
ld.param.u64 %rd1, [out];
mov.u32 %r0, %tid.x;
mov.u32 %r2, %ctaid.x;
mov.u32 %r3, %ntid.x;
mad.lo.u32 %r0, %r2, %r3, %r0;
mul.wide.u32 %rd2, %r0, 128;
add.u64 %rd0, %rd0, %rd2;
ld.volatile.global.u32 %r1, [%rd0];
prefetch.global.L1 [%rd0];
mul.wide.u32 %rd2, %r0, 8;
add.u64 %rd1, %rd1, %rd2;
ld.volatile.global.u32 %r0, [%rd0];
st.global.v2.u32 [%rd1], {%r1, %r0};
ret;
}

